# Analyze each changed pair
pairs = [
    (0, 'ihzwj', 'ikhhzgbj'),
    (1, 'wbigu', 'gbbgefuja'), 
    (4, 'jhuxwf', 'jhxygbf')
]

for idx, inp, outp in pairs:
    print(f"\nPair {idx}: '{inp}' -> '{outp}'")

    # Find differences character by character
    min_len = min(len(inp), len(outp))
    for i in range(min_len):
        if inp[i] != outp[i]:
            print(f"  Position {i}: '{inp[i]}' -> '{outp[i]}'")

    if len(inp) != len(outp):
        if len(inp) > len(outp):
            print(f"  Extra characters removed from end: '{inp[len(outp):]}'")
        else:
            print(f"  Extra characters added at end: '{outp[len(inp):]}'")

